import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Ihr erstes Grid","description":"Ein Grid anlegen, Einträge erfassen und Felder mit dem passenden Spaltentyp konfigurieren.","frontmatter":{"title":"Ihr erstes Grid","description":"Ein Grid anlegen, Einträge erfassen und Felder mit dem passenden Spaltentyp konfigurieren."},"headers":[],"relativePath":"grids/grid-anlegen.md","filePath":"grids/grid-anlegen.md","lastUpdated":1786092153000}'),a={name:"grids/grid-anlegen.md"};function l(s,e,d,o,h,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ihr-erstes-grid" tabindex="-1">Ihr erstes Grid <a class="header-anchor" href="#ihr-erstes-grid" aria-label="Permalink to &quot;Ihr erstes Grid&quot;">​</a></h1><p>Ein <strong>Grid</strong> ist eine Tabelle mit strukturierten Daten. Es ist der Ausgangspunkt für alles Weitere: Formulare schreiben in ein Grid, Ansichten zeigen ein Grid, Flows reagieren auf Änderungen in einem Grid.</p><h2 id="grid-anlegen" tabindex="-1">Grid anlegen <a class="header-anchor" href="#grid-anlegen" aria-label="Permalink to &quot;Grid anlegen&quot;">​</a></h2><ol><li>Öffnen Sie den Space, in dem das Grid entstehen soll.</li><li>Wählen Sie in der Seitenleiste im Bereich <strong>Grids</strong> die Schaltfläche <strong>Grid hinzufügen</strong>.</li><li>Vergeben Sie einen Namen.</li></ol><p>ApptiveGrid legt automatisch eine erste Ansicht an. Sie arbeiten also nie direkt „im Grid&quot;, sondern immer in einer Ansicht darauf — siehe <a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a>.</p><div class="tip custom-block"><p class="custom-block-title">Namen später ändern</p><p>Grids lassen sich jederzeit über das Kontextmenü umbenennen. Verknüpfungen, Formulare und Flows bleiben dabei erhalten, weil sie intern nicht über den Namen verweisen.</p></div><h2 id="eintrage-anlegen" tabindex="-1">Einträge anlegen <a class="header-anchor" href="#eintrage-anlegen" aria-label="Permalink to &quot;Einträge anlegen&quot;">​</a></h2><p>Ein <strong>Eintrag</strong> ist eine Zeile. Sie legen ihn auf drei Wegen an:</p><table tabindex="0"><thead><tr><th>Weg</th><th>Wann sinnvoll</th></tr></thead><tbody><tr><td>Direkt in der Tabelle</td><td>Beim Aufbau und für schnelle Korrekturen</td></tr><tr><td>Über die Detailansicht</td><td>Wenn viele Felder zu füllen sind</td></tr><tr><td>Über ein <a href="/formulare/formular-erstellen">Formular</a></td><td>Wenn andere Personen Daten liefern sollen</td></tr><tr><td>Über einen <a href="/flows/aktionen">Flow</a></td><td>Wenn Einträge automatisch entstehen sollen</td></tr></tbody></table><p>Ein Klick auf eine Zeile öffnet den Eintrag in der Detailansicht mit allen Feldern untereinander.</p><div class="warning custom-block"><p class="custom-block-title">Grenze für Einträge je Grid</p><p>Die Anzahl der Einträge pro Grid ist tarifabhängig. Nähern Sie sich der Grenze, blendet ApptiveGrid einen Hinweis ein.</p></div><h2 id="felder-anlegen" tabindex="-1">Felder anlegen <a class="header-anchor" href="#felder-anlegen" aria-label="Permalink to &quot;Felder anlegen&quot;">​</a></h2><p>Ein <strong>Feld</strong> ist eine Spalte. Jedes Feld hat einen <strong>Spaltentyp</strong>, der bestimmt:</p><ul><li>welche Werte zulässig sind,</li><li>wie der Wert dargestellt wird,</li><li>welche Filterbedingungen zur Verfügung stehen,</li><li>ob und wie er in Formularen abgefragt werden kann.</li></ul><p>So legen Sie ein Feld an:</p><ol><li>Klicken Sie am rechten Ende der Spaltenköpfe auf <strong>+</strong>.</li><li>Vergeben Sie einen <strong>Spaltennamen</strong>.</li><li>Wählen Sie den <strong>Spaltentyp</strong>.</li><li>Konfigurieren Sie den Typ, falls er Einstellungen hat (etwa Auswahloptionen oder eine Währung).</li></ol><h3 id="den-richtigen-spaltentyp-wahlen" tabindex="-1">Den richtigen Spaltentyp wählen <a class="header-anchor" href="#den-richtigen-spaltentyp-wahlen" aria-label="Permalink to &quot;Den richtigen Spaltentyp wählen&quot;">​</a></h3><p>Der Typ ist die wichtigste Entscheidung beim Anlegen eines Feldes. Eine grobe Orientierung:</p><table tabindex="0"><thead><tr><th>Sie wollen erfassen …</th><th>Spaltentyp</th></tr></thead><tbody><tr><td>Kurzen Text, Namen, Betreff</td><td><strong>Text</strong></td></tr><tr><td>Längeren, formatierten Text</td><td><strong>Formatierter Text</strong></td></tr><tr><td>Ganze Zahl (Menge, Anzahl)</td><td><strong>Zahl</strong></td></tr><tr><td>Zahl mit Nachkommastellen</td><td><strong>Kommazahl</strong></td></tr><tr><td>Geldbetrag</td><td><strong>Währung</strong></td></tr><tr><td>Datum ohne Uhrzeit</td><td><strong>Datum</strong></td></tr><tr><td>Datum mit Uhrzeit</td><td><strong>Datum und Uhrzeit</strong></td></tr><tr><td>Ja/Nein</td><td><strong>Häkchen</strong></td></tr><tr><td>Eine Option aus einer festen Liste</td><td><strong>Einzelauswahl</strong></td></tr><tr><td>Mehrere Optionen aus einer Liste</td><td><strong>Mehrfachauswahl</strong></td></tr><tr><td>Verweis auf einen Eintrag in einem anderen Grid</td><td><strong>Eintrag verknüpfen</strong></td></tr><tr><td>Verweise auf mehrere Einträge</td><td><strong>Mehrere Einträge verknüpfen</strong></td></tr><tr><td>Dateien und Bilder</td><td><strong>Dateien</strong></td></tr><tr><td>Postanschrift</td><td><strong>Adresse</strong></td></tr><tr><td>Geokoordinaten</td><td><strong>Geolokalisierung</strong></td></tr><tr><td>E-Mail-Adresse</td><td><strong>E-Mail</strong></td></tr><tr><td>Telefonnummer</td><td><strong>Telefon</strong></td></tr><tr><td>Webadresse</td><td><strong>Weblink</strong></td></tr><tr><td>Unterschrift</td><td><strong>Unterschrift</strong></td></tr></tbody></table><p>Die vollständige Liste mit allen Einstellungen steht in der <a href="/referenz/spaltentypen">Spaltentypen-Referenz</a>.</p><h3 id="automatisch-gefullte-felder" tabindex="-1">Automatisch gefüllte Felder <a class="header-anchor" href="#automatisch-gefullte-felder" aria-label="Permalink to &quot;Automatisch gefüllte Felder&quot;">​</a></h3><p>Drei Typen befüllt ApptiveGrid selbst — Sie können sie nicht bearbeiten:</p><ul><li><strong>Erstellt am</strong> — Zeitpunkt der Anlage</li><li><strong>Erstellt von</strong> — wer den Eintrag angelegt hat</li><li><strong>Benutzer</strong> — ein Verweis auf eine Person</li></ul><div class="tip custom-block"><p class="custom-block-title">„Erstellt von&quot; zeigt nicht nur Menschen</p><p>Wurde ein Eintrag über ein Formular angelegt, steht dort <em>Formular-Link</em>. Kam er über die Programmierschnittstelle, steht dort <em>API Zugangsdaten</em>. Das hilft bei der Frage, woher ein Datensatz stammt.</p></div><h3 id="berechnete-felder" tabindex="-1">Berechnete Felder <a class="header-anchor" href="#berechnete-felder" aria-label="Permalink to &quot;Berechnete Felder&quot;">​</a></h3><p>Drei Typen berechnen ihren Wert aus anderen Daten und sind ebenfalls schreibgeschützt:</p><ul><li><strong>Wert übernehmen</strong> — holt einen Wert aus einem verknüpften Eintrag</li><li><strong>Summe berechnen</strong> — summiert Werte über mehrere verknüpfte Einträge</li><li><strong>Formel</strong> — berechnet einen Wert aus einem Ausdruck</li></ul><p>Diese Typen setzen voraus, dass bereits eine Verknüpfung besteht. Details unter <a href="/grids/berechnete-felder">Berechnete Felder</a>.</p><h2 id="feld-andern" tabindex="-1">Feld ändern <a class="header-anchor" href="#feld-andern" aria-label="Permalink to &quot;Feld ändern&quot;">​</a></h2><p>Über das Menü im Spaltenkopf ändern Sie Name, Typ und Beschreibung.</p><div class="danger custom-block"><p class="custom-block-title">Typänderung kann Daten verlieren</p><p>Ändern Sie den Typ eines Feldes, versucht ApptiveGrid die vorhandenen Werte zu übernehmen. Passt ein Wert nicht zum neuen Typ, geht er verloren. Bei gefüllten Spalten sollten Sie vorher einen <a href="/grids/csv-export">CSV-Export</a> als Sicherung ziehen.</p></div><p>Zwei Fehlermeldungen treten hier regelmäßig auf:</p><p><strong>„Änderung nicht möglich. Dieses Feld wird in einem Filter verwendet.&quot;</strong> Ein Filter in einer Ansicht verweist auf dieses Feld. Entfernen Sie den Filter, dann ändern Sie das Feld.</p><p><strong>„Der Name existiert bereits&quot;</strong> Feldnamen müssen innerhalb eines Grids eindeutig sein.</p><h2 id="feld-loschen" tabindex="-1">Feld löschen <a class="header-anchor" href="#feld-loschen" aria-label="Permalink to &quot;Feld löschen&quot;">​</a></h2><p>Das Löschen erfordert eine Bestätigung, weil die Spalte samt Inhalt aus allen Einträgen verschwindet. Prüfen Sie vorher, ob Formulare, Ansichten, Filter oder Flows dieses Feld verwenden.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/verknuepfungen">Grids verknüpfen</a> — Daten über mehrere Grids verteilen</li><li><a href="/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a> — Daten unterschiedlich darstellen</li><li><a href="/formulare/formular-erstellen">Formular erstellen</a> — Daten von anderen erfassen lassen</li><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a> — alle Typen im Detail</li></ul>',38)])])}const c=n(a,[["render",l]]);export{p as __pageData,c as default};
